var a={en:`Up to 50 editors share a board, see cursors and reconnect after a network outage. Shapes must survive server restarts; presence does not.`,ua:`До 50 редакторів користуються дошкою, бачать курсори й перепідключаються після обриву. Фігури мають зберігатись після рестарту; присутність — ні.`};var n={en:[`Draw authenticated sockets, persistent changes, ephemeral presence and fanout.`,`Specify edit IDs, acknowledgements and reconnection replay.`,`Decide how concurrent edits are merged or ordered.`],ua:[`Намалюй авторизовані сокети, постійні зміни, тимчасову присутність і розсилання.`,`Визнач ID змін, підтвердження та відтворення при перепідключенні.`,`Обери порядок або злиття одночасних змін.`]};var s=[{en:`Durable edits have a persistence path.`,ua:`Постійні зміни мають шлях зберігання.`},{en:`Presence expiry cannot delete board content.`,ua:`Зникнення присутності не видаляє вміст дошки.`}];var t={scenario:a,tasks:n,checks:s};export{s as checks,t as default,a as scenario,n as tasks};